/// <summary>
/// validateDelete
/// </summary>
/// <returns>Result</returns>
public boolean validateDelete()
{
    boolean ret = super();   
    if(ret)
    {
        if(this.salesLineExists())
        {
            ret = checkFailed("@MET:SubCannotDeleteOrModifyExistsSalesLine");
        }
    }
    return ret;
}

    /// <summary>
    /// validateWrite
    /// </summary>
    /// <returns>Result</returns>
    public boolean validateWrite()
    {
        boolean ret = super();
        
        // date effectivity prompt

        if(this.ItemId == this.SubstituteItemId)
        {
            ret = checkFailed("@MET:SubItemAndSubItemMatchError");
        }

        if(this.SubstitutionCode != METSalesItemSubstitutionCode::Never)
           // CB166_SalesOrderSubstitutes deleted NoAlternative
            //this.SubstitutionCode != METSalesItemSubstitutionCode::NoAlternative)
        {
            if(!this.SubstituteItemId)
            {
                ret = checkFailed(strFmt("@MET:SubSubstituteItemMustBeSpecified",
                    fieldPName(METSalesItemSubstitute, SubstituteItemId),
                    this.SubstitutionCode));
            }
        }

        if(this.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId || 
            this.AccountCode == METSalesItemSubstitutionAccountCodeType::Table)
        {
            if(!this.AccountRelation)
            {
                ret = checkFailed(strFmt("@MET:SubFieldMustBeSpecified",
                    fieldPName(METSalesItemSubstitute, AccountRelation)));
            }
        }

        if(ret)
        {
            if(this.RecId && this.salesLineExists())
            {
                ret = checkFailed("@MET:SubCannotDeleteOrModifyExistsSalesLine");
            }
        }
        return ret;
    }

/// <summary>
/// Check if this entry is already referenced on a sales order line.
/// </summary>
/// <returns>Result</returns>
public boolean salesLineExists()
{
    METSalesLine   metSalesLine;
    select firstonly metSalesLine
        where   metSalesLine.SubstitutionType           == METSalesItemSubstitutionType::SubstitutionCode
        &&      metSalesLine.SubstitutionSetupRefRecID  == this.RecId;
    return metSalesLine.RecID != 0;
}

/// <summary>
/// initValue
/// </summary>
public void initValue()
{
    super(); 
   
    this.SubstitutionCode = METSalesItemSubstitutionCode::Always;
    this.modifiedField(fieldNum(METSalesItemSubstitute, SubstitutionCode));
}

    /// <summary>
    /// modifiedField
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);
        switch(_fieldId)
        {
            case fieldNum(METSalesItemSubstitute,AccountCode):
                // CB166_SalesOrderSubstitutes Account Type = All If there was a value in the “Account” field, it is set to blank.
                //if(this.AccountCode != METSalesItemSubstitutionAccountCodeType::All)
                //{
                this.AccountRelation = '';
                //}
                break;

            case fieldNum(METSalesItemSubstitute, SubstitutionCode):
                if(this.SubstitutionCode == METSalesItemSubstitutionCode::Always)
                {
                    this.DateEffectivityCategory = 1;                     
                }
                else
                {
                    this.DateEffectivityCategory = 1;   // **  confirm which sub. codes are considered matching for date-checks.
                }
                // CB166_SalesOrderSubstitutes deleted OrderOriginalItem
                //this.OrderOriginalItem = (this.SubstitutionCode == METSalesItemSubstitutionCode::OutOfStock);
                break;
        }
    }

/// <summary>
/// Record description (for logging)
/// </summary>
/// <returns>Description</returns>
public Description description()
{
    return strFmt("@MET:SubSubstitutionEntryDescription",
        this.SubstitutionCode,
        this.ItemId,
        this.SubstituteItemId,
        this.AccountCode,
        this.AccountRelation,
        this.ValidFrom);
}

    /// <summary>
    /// validateField
    /// </summary>
    /// <param name = "_fieldIdToCheck">Field id</param>
    /// <returns>True if validated</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);
    
        switch(_fieldIdToCheck)
        {
            // CB166_SalesOrderSubstitutes
            // However, if item B is marked as “Deleted”, a new record cannot be setup to configure item B as substitute item A 
            // (i.e. a “Deleted” item cannot be selected/entered into the “Substitute item” column).
            /*case fieldNum(METSalesItemSubstitute, ItemId):
                ret = METSalesItemSubstitute::itemIDCanBeSelected(this.ItemId, this.InventSiteId) && ret;
                break;*/
            case fieldNum(METSalesItemSubstitute, SubstituteItemId):
                ret = METSalesItemSubstitute::itemIDCanBeSelected(this.SubstituteItemId, this.InventSiteId) && ret;
                break;

            // Validate customers with customer groups listed in METTradingCustomer
            case fieldNum(METSalesItemSubstitute, AccountRelation):
                if (this.AccountCode == METSalesItemSubstitutionAccountCodeType::Table)
                {
                    CustTable custTable = CustTable::find(this.AccountRelation);
                    if (!METTradingCustomer::exist(CustTable::find(this.AccountRelation).CustGroup))
                    {
                        ret = checkFailed(strFmt("@MET:SubstitutesCusomterValidation", custTable.AccountNum, custTable.CustGroup)) && ret;
                    }
                }
                break;
        }

        return ret;
    }

/// <summary>
/// Check if item can be selected.
/// </summary>
/// <param name = "_itemID">Item number</param>
/// <param name = "_siteID">Inventory site</param>
/// <returns>True if the item can be selected</returns>
static public boolean itemIDCanBeSelected(ItemId _itemID, InventSiteId _siteID)
{
    if(_itemID && _siteID)
    {
        // CB166_SalesOrderSubstitutes
        /*MetItemSiteSettingsSetup itemSiteSettings = MetItemSiteSettingsSetup::find(_itemID, _siteID);
        if(itemSiteSettings)
        {
            if(itemSiteSettings.ItemStatus && itemSiteSettings.ItemStatus == 'Delete')  // ** TODO confirm whether this is specified elsewhere
            */
        if (METItemSiteSettingsSetup::isItemStatus(_itemID, _siteID, METConstants::Deleted))
        {
            return checkFailed(strFmt("@MET:SalesSubItemStatusWarning",
                _itemID,
                _siteID,
                METConstants::Deleted));
        }
    }
    return true;
}

    /// <summary>
    /// CB166_SalesOrderSubstitutes
    /// </summary>
    /// <param name = "_recId"><c>METSalesItemSubstitute</c> record id to find</param>
    /// <param name = "_forUpdate">Select record for update</param>
    /// <returns>Found <c>METSalesItemSubstitute</c> record</returns>
    static METSalesItemSubstitute findRecId(RecId    _recId,
                                            boolean  _forUpdate = false)
    {
        METSalesItemSubstitute salesItemSubstitute;

        if (_recId)
        {
            salesItemSubstitute.selectForUpdate(_forUpdate);

            select firstonly salesItemSubstitute
                where salesItemSubstitute.RecId == _recId;
        }

        return salesItemSubstitute;
    }

/// <summary>
/// CB166_SalesOrderSubstitutes
/// Clear the cacheKey when sales item substitute record is inserted
/// </summary>
public void insert()
{
    super();
    METSalesItemSubstituteCacheKey::removeSalesItemSubstituteCache(this);
}

/// <summary>
/// CB166_SalesOrderSubstitutes
/// Clear the cacheKey when sales item substitute record is deleted
/// </summary>
public void delete()
{
    super();
    METSalesItemSubstituteCacheKey::removeSalesItemSubstituteCache(this);
}

/// <summary>
/// CB166_SalesOrderSubstitutes
/// Clear the cacheKey when sales item substitute record is updated
/// </summary>
public void update()
{
    super();
    // delete cache for record (substitution code can be updated but not part of the cacheKey
    METSalesItemSubstituteCacheKey::removeSalesItemSubstituteCache(this);
}

    /// <summary>
    /// CB166_SalesOrderSubstitutes customer lookup filtered by customer groups from METTradingCustomer
    /// </summary>
    /// <param name="_lookupCtrl">
    /// A <c>FormStringControl</c> object.
    /// </param>
    public static void lookupCustomer(FormStringControl _lookupCtrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(CustTable), _lookupCtrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(CustTable));

        QueryBuildDataSource queryBuildDataSourceTradingCustomer = queryBuildDataSource.addDataSource(tableNum(METTradingCustomer));
        queryBuildDataSourceTradingCustomer.joinMode(JoinMode::ExistsJoin);
        queryBuildDataSourceTradingCustomer.addLink(fieldNum(CustTable, CustGroup), fieldNum(METTradingCustomer, CustGroup));

        sysTableLookup.addLookupfield(fieldNum(CustTable, AccountNum));
        sysTableLookup.addLookupfield(fieldNum(CustTable, Party));
        sysTableLookup.addLookupfield(fieldNum(CustTable, OurAccountNum));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }
